{"source":"def investigate(context, acquire):
    rows = []
    sqlite_sequence = 0
    open_transaction = False
    saved_rows = []
    saved_sequence = 0
    for action in context['actions']:
        op = action['op']
        if op == 'put':
            ident = action['id']
            rows.append(ident)
            if ident > sqlite_sequence:
                sqlite_sequence = ident
        elif op == 'delete':
            ident = action['id']
            if ident in rows:
                rows.remove(ident)
        elif op == 'begin':
            open_transaction = True
            saved_rows = list(rows)
            saved_sequence = sqlite_sequence
        elif op == 'commit':
            open_transaction = False
        elif op == 'rollback':
            open_transaction = False
            rows = list(saved_rows)
            sqlite_sequence = saved_sequence
    return sqlite_sequence + 1
","scope":"Model SQLite AUTOINCREMENT as the maximum ever inserted ID in the committed state, with BEGIN snapshotting both rows and the sequence, COMMIT retaining changes, and ROLLBACK restoring both.","change":"Added begin-time snapshots of rows and sqlite_sequence and restored both on rollback; commit now only closes the transaction. This fixes rolled-back inserts that previously leaked into the AUTOINCREMENT counter."}
